const body = $input.item.json.body || $input.item.json;
let rawPhone = '';
let customerName = 'Customer';
let message = '';
let channel = 'whatsapp';
const correlationId = 'corr_' + Math.random().toString(36).substring(2, 10) + '_' + Date.now();

if (body.entry && body.entry[0]?.changes && body.entry[0].changes[0]?.value) {
  const val = body.entry[0].changes[0].value;
  if (val.contacts && val.contacts[0]) {
    customerName = val.contacts[0].profile?.name || customerName;
  }
  if (val.messages && val.messages[0]) {
    const msgObj = val.messages[0];
    rawPhone = msgObj.from || '';
    if (msgObj.type === 'text') {
      message = msgObj.text?.body || '';
    } else if (msgObj.type === 'interactive') {
      message = msgObj.interactive?.button_reply?.title || msgObj.interactive?.list_reply?.title || '';
    } else if (msgObj.type === 'button') {
      message = msgObj.button?.text || '';
    }
  }
} else if (body.From || body.Body) {
  rawPhone = (body.From || '').replace('whatsapp:', '').trim();
  customerName = body.ProfileName || customerName;
  message = body.Body || '';
  channel = 'twilio';
} else {
  rawPhone = String(body.phone || body.from || body.sender || '').trim();
  customerName = body.name || body.customer_name || body.customerName || customerName;
  message = body.message || body.text || body.body || '';
}

// Canonical phone number normalization (Bug #29)
const cleanPhone = rawPhone.replace(/[^0-9]/g, '');

return [{
  json: {
    correlation_id: correlationId,
    phone: cleanPhone,
    customer_name: customerName,
    message: (message || '').trim(),
    channel: channel,
    received_at: new Date().toISOString()
  }
}];

const inbound = $('Parse_WhatsApp_Inbound').first().json;
const dbRes = $input.first()?.json || {};

// Explicit DB failure check (Bug #2)
const isDbError = Boolean(dbRes.error) || !Array.isArray(dbRes.active_doctors);
if (isDbError) {
  return [{
    json: {
      correlation_id: inbound.correlation_id,
      phone: inbound.phone,
      customer_name: inbound.customer_name,
      message: inbound.message,
      channel: inbound.channel,
      db_error: true,
      error_msg: "Database service is temporarily unavailable."
    }
  }];
}

const doctors = dbRes.active_doctors; // Can be [] if clinic has no active doctors (valid state)
const appts = Array.isArray(dbRes.recent_appointments) ? dbRes.recent_appointments : [];
const unavailability = Array.isArray(dbRes.active_unavailability) ? dbRes.active_unavailability : [];

// Check for active PENDING (that is NOT expired)
const now = new Date();
const activePending = appts.find(a => a.status === 'PENDING' && (!a.expires_at || new Date(a.expires_at) > now));
const activeConfirmed = appts.find(a => (a.status === 'CONFIRMED' || a.status === 'RESCHEDULED') && new Date(a.end_time) > now);

const clinicTimezone = doctors[0]?.timezone || 'Asia/Kolkata';
const todayLocalStr = new Intl.DateTimeFormat('en-CA', { timeZone: clinicTimezone }).format(now);
const todayWeekday = new Intl.DateTimeFormat('en-US', { timeZone: clinicTimezone, weekday: 'long' }).format(now);

const docListDesc = doctors.length > 0
  ? doctors.map(d => `- ID: "${d.doctor_id}", Name: "${d.doctor_name}", Specialty: "${d.specialty}", Working Hours: ${d.working_hours.start}-${d.working_hours.end}`).join('\n')
  : 'No doctors are currently available at the clinic.';

const prompt = `You are an intelligent clinic receptionist AI.
Today's local date is ${todayLocalStr} (${todayWeekday}) in ${clinicTimezone} timezone.

Doctors available at clinic:
${docListDesc}

Customer Info:
- Name: "${inbound.customer_name || 'Customer'}"
- Phone: "${inbound.phone}"
- Latest Message: "${inbound.message}"

Active Holds/Bookings:
- Pending Hold: ${activePending ? JSON.stringify(activePending) : 'None'}
- Confirmed Booking: ${activeConfirmed ? JSON.stringify(activeConfirmed) : 'None'}

Tasks:
Analyze the message and extract Intent and Entities.
Intents: "BOOK", "CHECK_AVAILABILITY", "CONFIRM", "RESCHEDULE", "CANCEL", "GENERAL_QUESTIONS", "UNKNOWN"
Rules:
- If customer says "YES", "CONFIRM", "OK", "Sure", "book it" and there is a Pending Hold -> Intent MUST be "CONFIRM".
- DO NOT invent calendar availability.
- If no doctors are available, inform the patient politely.
- Extract requested_date (YYYY-MM-DD), requested_time (HH:MM in 24h), doctor_id (must match one of [${doctors.map(d => d.doctor_id).join(', ')}]), service.

Output MUST be a single raw JSON object:
{
  "intent": "BOOK" | "CHECK_AVAILABILITY" | "CONFIRM" | "RESCHEDULE" | "CANCEL" | "GENERAL_QUESTIONS" | "UNKNOWN",
  "doctor_id": string | null,
  "service": string | null,
  "requested_date": "YYYY-MM-DD" | null,
  "requested_time": "HH:MM" | null,
  "general_answer": string | null
}`;

return [{
  json: {
    correlation_id: inbound.correlation_id,
    phone: inbound.phone,
    customer_name: inbound.customer_name,
    message: inbound.message,
    channel: inbound.channel,
    db_error: false,
    active_doctors: doctors,
    active_pending: activePending || null,
    active_confirmed: activeConfirmed || null,
    active_unavailability: unavailability,
    today_local: todayLocalStr,
    clinic_timezone: clinicTimezone,
    gemini_model: "gemini-1.5-flash",
    gemini_prompt: prompt
  }
}];

const prev = $('Merge_Context_For_AI').first().json;
const response = $input.item.json;
const doctors = prev.active_doctors || [];

let isError = false;
let errorMessage = '';

let aiResult = {
  intent: 'GENERAL_QUESTIONS',
  doctor_id: doctors[0]?.doctor_id || 'dr_smith',
  service: 'General Consultation',
  requested_date: null,
  requested_time: null,
  general_answer: null
};

const cleanMsg = (prev.message || '').trim().toLowerCase();
const isDirectConfirm = ['yes', 'confirm', 'y', 'sure', 'ok', 'okay', 'proceed', 'book it', 'yes please', 'confirm please'].includes(cleanMsg);

if (prev.active_pending && isDirectConfirm) {
  aiResult.intent = 'CONFIRM';
  aiResult.doctor_id = prev.active_pending.doctor_id;
  aiResult.service = prev.active_pending.service;
} else if (response && response.candidates && response.candidates[0]?.content?.parts?.[0]?.text) {
  try {
    let rawText = response.candidates[0].content.parts[0].text.trim();
    if (rawText.startsWith('```json')) {
      rawText = rawText.replace(/^```json\n?/, '').replace(/\n?```$/, '');
    } else if (rawText.startsWith('```')) {
      rawText = rawText.replace(/^```\n?/, '').replace(/\n?```$/, '');
    }
    const parsed = JSON.parse(rawText);
    aiResult = { ...aiResult, ...parsed };
  } catch (e) {
    isError = true;
    errorMessage = 'Failed to parse AI intent response.';
  }
} else {
  // Gemini failed (HTTP status != 200 or no text) (Bug #13)
  // Fail safely: DO NOT treat as UNKNOWN or book/cancel
  isError = true;
  errorMessage = 'AI service temporarily unavailable.';
}

// Validate doctor_id against DB active doctors list (Bug #13)
let matchedDoctor = doctors.find(d => d.doctor_id === aiResult.doctor_id);
if (!matchedDoctor) {
  matchedDoctor = doctors.find(d => d.doctor_id === prev.active_pending?.doctor_id) ||
                  doctors.find(d => d.doctor_id === prev.active_confirmed?.doctor_id) ||
                  doctors[0];
}

// Validate requested_date format YYYY-MM-DD
if (aiResult.requested_date && !/^\d{4}-\d{2}-\d{2}$/.test(aiResult.requested_date)) {
  aiResult.requested_date = null;
}
// Validate requested_time format HH:MM
if (aiResult.requested_time && !/^\d{2}:\d{2}$/.test(aiResult.requested_time)) {
  aiResult.requested_time = null;
}

return [{
  json: {
    correlation_id: prev.correlation_id,
    phone: prev.phone,
    customer_name: prev.customer_name,
    message: prev.message,
    channel: prev.channel,
    is_ai_error: isError,
    ai_error_message: errorMessage,
    intent: isError ? 'AI_ERROR' : (aiResult.intent || 'GENERAL_QUESTIONS').toUpperCase(),
    doctor: matchedDoctor,
    service: aiResult.service || 'General Consultation',
    requested_date: aiResult.requested_date,
    requested_time: aiResult.requested_time,
    general_answer: aiResult.general_answer,
    active_pending: prev.active_pending,
    active_confirmed: prev.active_confirmed,
    active_unavailability: prev.active_unavailability,
    active_doctors: prev.active_doctors
  }
}];

function getUtcFromLocal(dateStr, timeStr, timeZone) {
  const [yyyy, mm, dd] = dateStr.split('-').map(Number);
  const [hh, min] = timeStr.split(':').map(Number);
  const utcDate = new Date(Date.UTC(yyyy, mm - 1, dd, hh, min, 0));
  const invDate = new Date(utcDate.toLocaleString('en-US', { timeZone: 'UTC' }));
  const targetDate = new Date(utcDate.toLocaleString('en-US', { timeZone: timeZone }));
  const diff = targetDate.getTime() - invDate.getTime();
  return new Date(utcDate.getTime() - diff);
}

function formatInTimezone(dateObj, timeZone, options) {
  return new Intl.DateTimeFormat('en-US', { timeZone, ...options }).format(dateObj);
}

function getLocalWeekday(dateStr, timeStr, timeZone) {
  const d = getUtcFromLocal(dateStr, timeStr || '12:00', timeZone);
  const dayStr = new Intl.DateTimeFormat('en-US', { timeZone, weekday: 'short' }).format(d);
  const map = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  return map[dayStr];
}

const item = $input.item.json;
const doc = item.doctor || {};
const tz = doc.timezone || 'Asia/Kolkata';
const wh = doc.working_hours || { start: "09:00", end: "17:00" };
const workingDays = doc.working_days || [1, 2, 3, 4, 5, 6];
const slotDuration = doc.slot_duration_minutes || 30;
const bufferMin = doc.buffer_minutes || 0;
const cutoffMin = doc.booking_cutoff_minutes || 60;
const unavailList = item.active_unavailability || [];

let needsInfo = false;
let missingFields = [];
let replyMsg = '';

if (!item.requested_date) {
  needsInfo = true;
  missingFields.push('preferred date (YYYY-MM-DD or tomorrow)');
}
if (!item.requested_time) {
  needsInfo = true;
  missingFields.push('preferred time (e.g. 10:00 AM)');
}

let startUtc = null;
let endUtc = null;

if (needsInfo) {
  replyMsg = `Hello ${item.customer_name || 'there'}! To check availability with ${doc.doctor_name}, please provide your ${missingFields.join(' and ')}.`;
} else {
  // 1. Timezone-aware date construction (Bug #5)
  startUtc = getUtcFromLocal(item.requested_date, item.requested_time, tz);
  endUtc = new Date(startUtc.getTime() + slotDuration * 60000);

  // 2. Working day check (Bug #6)
  const localDayOfWeek = getLocalWeekday(item.requested_date, item.requested_time, tz);
  if (!workingDays.includes(localDayOfWeek)) {
    needsInfo = true;
    replyMsg = `Sorry, ${doc.doctor_name} does not take appointments on that day. Available days: Monday-Saturday.`;
  } else {
    // 3. Working hours check (Bug #7)
    const [startH, startM] = wh.start.split(':').map(Number);
    const [endH, endM] = wh.end.split(':').map(Number);
    const [reqH, reqM] = item.requested_time.split(':').map(Number);
    const reqMin = reqH * 60 + reqM;
    const openMin = startH * 60 + startM;
    const closeMin = endH * 60 + endM;

    if (reqMin < openMin || reqMin + slotDuration > closeMin) {
      needsInfo = true;
      replyMsg = `Operating hours for ${doc.doctor_name} are ${wh.start} to ${wh.end}. The requested time (${item.requested_time}) is outside working hours.`;
    }
  }

  // 4. Booking cutoff check (Bug #9)
  const now = new Date();
  if (startUtc.getTime() < now.getTime() + cutoffMin * 60000) {
    needsInfo = true;
    replyMsg = `Appointments must be scheduled at least ${cutoffMin} minutes in advance. Please choose a later slot.`;
  }

  // 5. Doctor Leave / Unavailability check (Bug #3)
  for (const u of unavailList) {
    if (u.doctor_id === doc.doctor_id) {
      const uStart = new Date(u.start_time);
      const uEnd = new Date(u.end_time);
      if (startUtc < uEnd && endUtc > uStart) {
        needsInfo = true;
        replyMsg = `Sorry, ${doc.doctor_name} is unavailable on ${item.requested_date} (${u.reason || 'Leave'}). Please pick another date.`;
        break;
      }
    }
  }
}

// Calculate search window for GCal: doctor local midnight to next local midnight (Bug #5)
let gcalMin = new Date().toISOString();
let gcalMax = new Date(Date.now() + 86400000).toISOString();
if (item.requested_date) {
  gcalMin = getUtcFromLocal(item.requested_date, '00:00', tz).toISOString();
  gcalMax = getUtcFromLocal(item.requested_date, '23:59', tz).toISOString();
}

return [{
  json: {
    ...item,
    needs_info: needsInfo,
    missing_fields: missingFields,
    missing_info_message: replyMsg,
    start_time_iso: startUtc ? startUtc.toISOString() : null,
    end_time_iso: endUtc ? endUtc.toISOString() : null,
    gcal_time_min: gcalMin,
    gcal_time_max: gcalMax
  }
}];

function getUtcFromLocal(dateStr, timeStr, timeZone) {
  const [yyyy, mm, dd] = dateStr.split('-').map(Number);
  const [hh, min] = timeStr.split(':').map(Number);
  const utcDate = new Date(Date.UTC(yyyy, mm - 1, dd, hh, min, 0));
  const invDate = new Date(utcDate.toLocaleString('en-US', { timeZone: 'UTC' }));
  const targetDate = new Date(utcDate.toLocaleString('en-US', { timeZone: timeZone }));
  const diff = targetDate.getTime() - invDate.getTime();
  return new Date(utcDate.getTime() - diff);
}

function formatInTimezone(dateObj, timeZone, options) {
  return new Intl.DateTimeFormat('en-US', { timeZone, ...options }).format(dateObj);
}

function getLocalWeekday(dateStr, timeStr, timeZone) {
  const d = getUtcFromLocal(dateStr, timeStr || '12:00', timeZone);
  const dayStr = new Intl.DateTimeFormat('en-US', { timeZone, weekday: 'short' }).format(d);
  const map = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  return map[dayStr];
}

const prev = $('Validate_Booking_Input').first().json;
const allInputs = $input.all();

// Explicit Google Calendar failure detection (Bug #4)
const gcalError = allInputs.some(i => i.json?.error || i.error);
if (gcalError) {
  return [{
    json: {
      ...prev,
      is_slot_available: false,
      calendar_error: true,
      available_alternatives: [],
      error_msg: "We are temporarily unable to verify calendar availability. Please try again shortly."
    }
  }];
}

const gcalItems = allInputs.map(i => i.json).filter(j => j && (j.id || j.start));

const doc = prev.doctor || {};
const tz = doc.timezone || 'Asia/Kolkata';
const wh = doc.working_hours || { start: "09:00", end: "17:00" };
const slotDuration = doc.slot_duration_minutes || 30;
const bufferMin = doc.buffer_minutes || 0;
const cutoffMin = doc.booking_cutoff_minutes || 60;
const unavailList = prev.active_unavailability || [];

const reqStart = new Date(prev.start_time_iso);
const reqEnd = new Date(prev.end_time_iso);

function isGCalOverlap(startA, endA, events) {
  for (const ev of events) {
    const evStartStr = ev.start?.dateTime || ev.start?.date;
    const evEndStr = ev.end?.dateTime || ev.end?.date;
    if (!evStartStr || !evEndStr) continue;
    const evStart = new Date(evStartStr);
    const evEnd = new Date(evEndStr);
    const evStartBuffered = new Date(evStart.getTime() - bufferMin * 60000);
    const evEndBuffered = new Date(evEnd.getTime() + bufferMin * 60000);
    if (startA < evEndBuffered && endA > evStartBuffered) {
      return true;
    }
  }
  return false;
}

function isDoctorLeaveOverlap(startA, endA, leaveList) {
  for (const u of leaveList) {
    if (u.doctor_id === doc.doctor_id) {
      const uStart = new Date(u.start_time);
      const uEnd = new Date(u.end_time);
      if (startA < uEnd && endA > uStart) return true;
    }
  }
  return false;
}

const isRequestedFree = !isGCalOverlap(reqStart, reqEnd, gcalItems) && !isDoctorLeaveOverlap(reqStart, reqEnd, unavailList);

const [startH, startM] = wh.start.split(':').map(Number);
const [endH, endM] = wh.end.split(':').map(Number);
const allAlternatives = [];
const now = new Date();

for (let h = startH; h < endH; h++) {
  for (let m = 0; m < 60; m += slotDuration) {
    const hhStr = String(h).padStart(2, '0');
    const mmStr = String(m).padStart(2, '0');
    const timeStr = `${hhStr}:${mmStr}`;

    const slotStart = getUtcFromLocal(prev.requested_date, timeStr, tz);
    const slotEnd = new Date(slotStart.getTime() + slotDuration * 60000);

    if (slotStart.getTime() < now.getTime() + cutoffMin * 60000) continue;

    if (!isGCalOverlap(slotStart, slotEnd, gcalItems) && !isDoctorLeaveOverlap(slotStart, slotEnd, unavailList)) {
      allAlternatives.push(timeStr);
    }
  }
}

return [{
  json: {
    ...prev,
    is_slot_available: isRequestedFree,
    calendar_error: false,
    available_alternatives: allAlternatives.slice(0, 4),
    existing_events_count: gcalItems.length
  }
}];

const item = $input.item.json;
const alts = item.available_alternatives || [];
let msg = '';

if (alts.length > 0) {
  msg = `⚠️ Sorry, ${item.doctor.doctor_name} is not available on ${item.requested_date} at ${item.requested_time}.\n\nHere are alternative open slots on ${item.requested_date}:\n` +
        alts.map(s => `🔹 ${s}`).join('\n') +
        `\n\nPlease reply with your preferred time to hold the booking.`;
} else {
  msg = `⚠️ Sorry, all appointment slots for ${item.doctor.doctor_name} are fully booked on ${item.requested_date}.\n\nPlease suggest another date and we will check availability immediately!`;
}

return [{ json: { ...item, unavailable_whatsapp_msg: msg } }];

