const prev = $('Calculate_Available_Slots').first().json;
const apptItem = $input.item.json;

if (!apptItem || !apptItem.appointment_id || apptItem.error) {
  const alts = (prev.available_alternatives || []).join(', ');
  const altText = alts ? `\nAvailable alternative times: ${alts}` : '';
  return [{
    json: {
      ...prev,
      pending_whatsapp_msg: `⚠️ *Slot Unavailable*\n\nSomeone just reserved this time slot. Please choose another time.${altText}`
    }
  }];
}

const message = `📋 *APPOINTMENT HOLD (PENDING CONFIRMATION)*\n\n` +
`👤 Patient: ${prev.customer_name}\n` +
`👨‍⚕️ Doctor: ${prev.doctor.doctor_name}\n` +
`💼 Service: ${prev.service}\n` +
`📅 Date: ${prev.requested_date}\n` +
`⏰ Time: ${prev.requested_time} (${prev.doctor.timezone})\n\n` +
`This slot is held for you for the next 15 minutes.\n` +
`👉 *Reply YES or CONFIRM to finalize your booking.*`;

return [{
  json: {
    ...prev,
    appointment_id: apptItem.appointment_id,
    pending_whatsapp_msg: message
  }
}];

const prev = $input.item.json;
const pending = prev.active_pending;
const now = new Date();

if (!pending || !pending.start_time || !pending.end_time || (pending.expires_at && new Date(pending.expires_at) <= now)) {
  return [{
    json: {
      ...prev,
      has_valid_pending: false,
      error_msg: "You do not currently have an active held appointment (or the hold expired). Please reply with a date and time to start a new booking."
    }
  }];
}

return [{
  json: {
    ...prev,
    has_valid_pending: true,
    appointment_id: pending.appointment_id,
    start_time_iso: new Date(pending.start_time).toISOString(),
    end_time_iso: new Date(pending.end_time).toISOString(),
    doctor_id: pending.doctor_id,
    doctor_name: pending.doctor_name || prev.doctor?.doctor_name,
    calendar_id: pending.calendar_id || prev.doctor?.calendar_id,
    timezone: pending.timezone || prev.doctor?.timezone || 'Asia/Kolkata',
    service: pending.service,
    customer_name: pending.customer_name || prev.customer_name
  }
}];

function getUtcFromLocal(dateStr, timeStr, timeZone) {
  const [yyyy, mm, dd] = dateStr.split('-').map(Number);
  const [hh, min] = timeStr.split(':').map(Number);
  const utcDate = new Date(Date.UTC(yyyy, mm - 1, dd, hh, min, 0));
  const invDate = new Date(utcDate.toLocaleString('en-US', { timeZone: 'UTC' }));
  const targetDate = new Date(utcDate.toLocaleString('en-US', { timeZone: timeZone }));
  const diff = targetDate.getTime() - invDate.getTime();
  return new Date(utcDate.getTime() - diff);
}

function formatInTimezone(dateObj, timeZone, options) {
  return new Intl.DateTimeFormat('en-US', { timeZone, ...options }).format(dateObj);
}

function getLocalWeekday(dateStr, timeStr, timeZone) {
  const d = getUtcFromLocal(dateStr, timeStr || '12:00', timeZone);
  const dayStr = new Intl.DateTimeFormat('en-US', { timeZone, weekday: 'short' }).format(d);
  const map = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  return map[dayStr];
}

const prev = $('Validate_Pending_For_Confirm').first().json;
const allInputs = $input.all();

// Explicit Google Calendar failure detection (Bug #3, Bug #4)
const gcalError = allInputs.some(i => i.json?.error || i.error);
if (gcalError) {
  return [{
    json: {
      ...prev,
      is_final_slot_free: false,
      calendar_check_failed: true,
      error_msg: "We are temporarily unable to verify calendar availability. Your booking hold is still saved. Please try confirming again in a moment by replying YES."
    }
  }];
}

const gcalItems = allInputs.map(i => i.json).filter(j => j && (j.id || j.start));
const reqStart = new Date(prev.start_time_iso);
const reqEnd = new Date(prev.end_time_iso);
const now = new Date();

let isFree = true;
let reason = "";

// 1. Check pending expiration and status
if (!prev.active_pending || prev.active_pending.status !== 'PENDING') {
  isFree = false;
  reason = "Appointment is no longer in PENDING state.";
} else if (prev.active_pending.expires_at && new Date(prev.active_pending.expires_at) <= now) {
  isFree = false;
  reason = "Appointment hold has expired.";
}

// 2. Validate Doctor exists and is active
const doc = (prev.active_doctors || []).find(d => d.doctor_id === prev.doctor_id) || prev.doctor;
if (!doc) {
  isFree = false;
  reason = "Doctor not found or inactive.";
}

// 3. Validate working days and working hours
if (isFree && doc) {
  const tz = doc.timezone || 'Asia/Kolkata';
  const weekdayNum = getLocalWeekday(formatInTimezone(reqStart, tz, { year: 'numeric', month: '2-digit', day: '2-digit' }).replace(/\//g, '-'), '12:00', tz);
  const workingDays = doc.working_days || [1,2,3,4,5,6];
  if (!workingDays.includes(weekdayNum)) {
    isFree = false;
    reason = "Requested date is not a working day for this doctor.";
  }
}

// 4. Validate Doctor Leave / Unavailability
if (isFree) {
  const unavailList = prev.active_unavailability || [];
  for (const u of unavailList) {
    if (u.doctor_id === prev.doctor_id) {
      const uStart = new Date(u.start_time);
      const uEnd = new Date(u.end_time);
      if (reqStart < uEnd && reqEnd > uStart) {
        isFree = false;
        reason = `Doctor is unavailable: ${u.reason || 'On Leave'}`;
        break;
      }
    }
  }
}

// 5. Check GCal events overlap
if (isFree) {
  for (const ev of gcalItems) {
    const evStartStr = ev.start?.dateTime || ev.start?.date;
    const evEndStr = ev.end?.dateTime || ev.end?.date;
    if (!evStartStr || !evEndStr) continue;
    const evStart = new Date(evStartStr);
    const evEnd = new Date(evEndStr);
    if (reqStart < evEnd && reqEnd > evStart) {
      isFree = false;
      reason = "Slot is already booked on the doctor's calendar.";
      break;
    }
  }
}

return [{
  json: {
    ...prev,
    is_final_slot_free: isFree,
    calendar_check_failed: false,
    conflict_reason: reason
  }
}];

